import React, { useState, useEffect } from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import { Helmet } from 'react-helmet-async';
import { Card, Grid, Button, Typography, Box, Switch } from '@mui/material';
import 'dayjs/locale/en-gb';
import InputLabel from '@mui/material/InputLabel';
import { axios } from '../../utils/axios';
import { IMAGE_URL } from '../../utils/config';
import { useMyContext } from '../provider';
import GenerateToastConfig from '../../components/toast-config/GenerateToastConfig';
import GoBackButton from '../../components/goBackButton/GoBackButton';
import InputField from '../../components/input/inputField';
import useResponsive from '../../hooks/useResponsive';

export default function EditCategory() {
  const navigate = useNavigate();
  const location = useLocation();
  const { category, catids, isAll, allCategories } = location?.state || { cate: '', catids: '', img: '' };

  const [amenityCategory, setAmenityCategory] = useState('');
  const [iconFile, setIconFile] = useState(null);
  const [iconpreview, setIconpreview] = useState(null);
  const [imageFile, setImageFile] = useState(null);
  const [imagepreview, setImagepreview] = useState(null);
  const { i18 } = useMyContext();
  const isMobile = useResponsive('down', 'sm');
  const [allCategoryToggle, setAllCategoryToggle] = useState(isAll);

  useEffect(() => {
    if (location.state && location.state.icon) {
      setIconpreview(IMAGE_URL + location.state.icon);
    }
    if (location.state && location.state.image) {
      setImagepreview(IMAGE_URL + location.state.image);
    }
  }, [location.state]);

  // if (!location && !location?.state)
  //   return null;

  const isAddButtonDisabled = !iconFile && !imageFile && !amenityCategory;
  const backtouser = () => {
    navigate('/dashboard/category', { state: { cate: category } });
  };
  const handleIconChange = (e) => {
    const file = e.target.files[0];
    const reader = new FileReader();

    reader.onloadend = () => {
      setIconpreview(reader.result);
      setIconFile(file);
    };

    if (file) {
      reader.readAsDataURL(file);
    }
  };

  const handleImageChange = (e) => {
    const file = e.target.files[0];
    const reader = new FileReader();

    reader.onloadend = () => {
      setImagepreview(reader.result);
      setImageFile(file);
    };

    if (file) {
      reader.readAsDataURL(file);
    }
  };

  const handleAllCategoryToggle = (event) => {
    setAllCategoryToggle(event.target.checked)
  };
  
  const updateCategory = async () => {
    try {
      const formData = new FormData();
      if (amenityCategory) formData.append('category', amenityCategory);
      formData.append('isAll', allCategoryToggle)
      if (iconFile) formData.append('icon', iconFile);
      if (imageFile) formData.append('image', imageFile);

      const res = await axios.put(`module/admin/category/${catids}`, formData);
      if (res.status === 200) {
        GenerateToastConfig(res.data.message, 'success');
        navigate('/dashboard/category');
      } else {
        GenerateToastConfig(res.data.message);
      }
    } catch (err) {
      GenerateToastConfig(err?.response?.data?.message);
    }
  };

  return (
    <>
      <Helmet>
        <title> Edit Category </title>
      </Helmet>

      <Card sx={{ padding: '20px 10px', margin: '30px 0px' }}>
        <Grid container sx={{ borderBottom: '1px solid #dbe0e4', padding: '10px 0px' }}>
          <Grid container item justifyContent="space-between" alignItems="center" sx={{ marginRight: '10px' }}>
            <Typography variant="h6" gutterBottom sx={{ margin: '0px 0px 0px 10px', paddingBottom: '0px' }}>
              {i18?.LISTINGPAGE?.EDIT_CATEGORY || "Edit Category"}
            </Typography>
            <GoBackButton
              label={i18?.LISTINGPAGE?.GO_BACK || "Go Back"}
              onClick={backtouser}
              icon="icon-park-twotone:back"
            />
          </Grid>
        </Grid>
        <>
        <Grid container={!isMobile} sx={{ marginTop: '10px', padding: '0px 5px' }}>
          <Grid item xs={allCategories && isAll ? 6 : 12} sx={ allCategories && isAll && { padding: !isMobile ? '0px 10px 0px 0px' : '0px 0px 10px 0px' } }>
            <InputField
              label={i18?.LISTINGPAGE?.CATEGORY_NAME || "Category Name"}
              sx={{ margin: '10px 0px', width: '100%' }}
              name="FirstName"
              defaultValue={category}
              onChange={(e) => setAmenityCategory(e.target.value)}
            />
          </Grid>
          {allCategories && isAll &&<Grid item xs={6}>
            <InputLabel>{i18?.LISTINGPAGE?.ALL_CATEGORY || "All Category"}</InputLabel>
            <Box
              sx={{
                border: '1px solid #ccc',
                borderRadius: '4px',
                padding: '8px',
                margin: '10px 0',
                display: 'flex',
                justifyContent: 'space-between',
                alignItems: 'center',
              }}
            >
              <Typography>{i18?.LISTINGPAGE?.ALL_CATEGORY || "All Category"}</Typography>
              <Switch
                checked={allCategoryToggle}
                onChange={handleAllCategoryToggle}
                color='primary'
              />
            </Box>
          </Grid>}
        </Grid>

        <Grid container={!isMobile} sx={{ padding: '0px 5px' }}>
          <Grid item xs={6} sx={{ padding: !isMobile ? '0px 10px 0px 0px' : '0px 0px 10px 0px' }}>
            <InputLabel
              id="demo-simple-select-label"
              position={'absolute'}
              sx={{
                cursor: 'pointer',
                border: '1px solid #adb5bd',
                borderRadius: '5px',
                padding: '15px',
                width: '100%',
              }}
            >
              <input
                type="file"
                id="image-upload"
                style={{ display: 'none' }}
                onChange={(e) => handleIconChange(e)}
              />
              <span style={{ color: 'black' }}>{i18?.LISTINGPAGE?.UPLOAD_ICON || "Upload Icon"}</span>
              {iconpreview && (
                <img
                  src={iconpreview}
                  alt="Preview"
                  style={{ maxWidth: '50px', position: 'relative', left: '25px', width: '70px', marginTop: '8px' }}
                />
              )}
            </InputLabel>
          </Grid>
          <Grid item xs={6}>
            <InputLabel
              id="demo-simple-select-label"
              position={'absolute'}
              sx={{
                cursor: 'pointer',
                border: '1px solid #adb5bd',
                borderRadius: '5px',
                padding: '15px',
                width: '100%',
              }}
            >
              <input
                type="file"
                id="image-upload"
                accept="image/*"
                style={{ display: 'none' }}
                onChange={(e) => handleImageChange(e)}
              />
              <span style={{ color: 'black' }}>{i18?.LISTINGPAGE?.UPLOAD_IMAGE || "Upload Image"}</span>
              {imagepreview && (
                <img
                  src={imagepreview}
                  alt="Preview"
                  style={{ maxWidth: '50px', position: 'relative', left: '25px', width: '70px', marginTop: '8px' }}
                />
              )}
            </InputLabel>
          </Grid>
        </Grid>
        </>
        <Grid container justifyContent="flex-end" sx={{ paddingRight: '20px', bottom: '10px' }}>
          <Button variant="contained" disabled={isAddButtonDisabled} onClick={updateCategory}>
            {i18?.LISTINGPAGE?.UPDATE || "Update"}
          </Button>
        </Grid>
      </Card>

    </>
  )
}